#!/usr/bin/env perl
# Generated by the Superpowers bootstrap — steers shell searches to ripgrep: a
# command running a recursive grep (grep -r) or a name search (find -name/-path)
# is denied with the rg equivalent. Pipes (`... | grep x`), git grep and the
# agents' built-in search tools are not affected. Allows everything when no rg
# is available. Re-running the bootstrap overwrites this file.
#
# Usage: perl search-guard.pl claude|codex|copilot|cursor|antigravity < hook-input.json
use strict;
use warnings;
use Cwd qw(abs_path);
use JSON::PP;

my $format = $ARGV[0] // 'copilot';
my $raw = do { local $/; <STDIN> } // '';
my $in = eval { JSON::PP->new->decode($raw) };
exit 0 unless ref $in eq 'HASH';

# Each harness names the tool call differently (see secret-guard.pl).
my $args;
if (ref $in->{toolCall} eq 'HASH') { $args = $in->{toolCall}{args} }
elsif (exists $in->{tool_input})   { $args = $in->{tool_input} }
elsif (exists $in->{toolArgs})     { $args = $in->{toolArgs} }
else { $args = { map { exists $in->{$_} ? ($_ => $in->{$_}) : () } qw(command) } }
$args = (eval { JSON::PP->new->decode($args) } // { command => $args }) if defined $args && !ref $args;
exit 0 unless ref $args eq 'HASH';
my @commands = map { ref $args->{$_} eq 'ARRAY' ? join(' ', @{ $args->{$_} }) : $args->{$_} }
  grep { /^(command|cmd|script|commandline)$/i && defined $args->{$_} } keys %$args;
exit 0 unless @commands;

my $root = $ENV{CLAUDE_PROJECT_DIR} // do {
  my $self = abs_path($0) // $0;
  $self =~ s{/[^/]+/hooks/[^/]+$}{};
  $self;
};
my $local_rg = grep { -x "$root/.agents/bin/$_" } qw(rg rg.exe);
my $path_rg = grep { my $d = $_; grep { -x "$d/$_" } qw(rg rg.exe) } split /[:;]/, $ENV{PATH} // '';
exit 0 unless $local_rg || $path_rg;

# the first word of each simple command, past VAR=value, sudo, env, time ...
sub offending {
  for my $segment (split /\|\||&&|[;|&\n]|\$\(|`/, shift) {
    my @words = grep { length } split /\s+/, $segment;
    shift @words while @words && ($words[0] =~ /^\w+=/ || $words[0] =~ /^(sudo|env|time|nice|command|exec|\()$/);
    next unless @words;
    (my $cmd = $words[0]) =~ s{.*/}{};
    my @rest = @words[1 .. $#words];
    return 'grep -r' if $cmd =~ /^[ef]?grep$/ && grep { /^-[A-Za-z]*[rR]/ || /^--(recursive|dereference-recursive)$/ } @rest;
    return 'find -name' if $cmd eq 'find' && grep { /^-i?(name|path|wholename|regex)$/ } @rest;
  }
  return;
}

my ($hit) = grep { defined } map { offending($_) } @commands;
exit 0 unless defined $hit;

my $rg = $path_rg ? 'rg' : '.agents/bin/rg';
my $reason = "This project uses ripgrep for searching, not $hit. Use `$rg PATTERN [PATH]` "
  . "(add -i, -w, -F, -g 'GLOB', -t TYPE as needed) for content, and `$rg --files -g 'GLOB'` "
  . "for file names. rg is recursive and skips .gitignore'd files by default (--hidden / --no-ignore to include them).";
my $json = JSON::PP->new->canonical;
if ($format eq 'antigravity') {
  print $json->encode({ decision => 'deny', reason => $reason }), "\n";
  exit 0;
}
if ($format eq 'cursor') {
  print $json->encode({ permission => 'deny', user_message => $reason, agent_message => $reason }), "\n";
} elsif ($format eq 'copilot') {
  print $json->encode({ permissionDecision => 'deny', permissionDecisionReason => $reason }), "\n";
}
print STDERR "$reason\n";
exit 2;
